// ==========================================
// 1. Lectura de parámetros de entrada
// ==========================================

// Obtiene el texto crudo que contiene los términos de búsqueda.
// Se espera que venga desde el JSON de entrada en la propiedad "search_terms_raw".
// Si no existe esa propiedad, se usa una cadena vacía para evitar errores.
const raw = String($json.search_terms_raw || '');

// Obtiene el año inicial desde el cual se hará la búsqueda.
// Si el usuario no envía un valor, se usa "2016" como valor por defecto.
// trim() elimina espacios en blanco al inicio y al final.
const fromYear = String($json.from_year || '2016').trim();

// Obtiene la cantidad de resultados que se solicitarán por cada fuente consultada.
// Si no se especifica en la entrada, se usa 20 por defecto.
// Number() asegura que el valor quede como número y no como texto.
const rows = Number($json.rows_per_source || 20);


// ==========================================
// 2. Separación y limpieza de términos
// ==========================================

// Convierte el texto crudo en un arreglo de términos independientes.
// El usuario puede escribir términos:
// - uno por línea
// - o separados por punto y coma
//
// Ejemplo de entrada:
// "artificial intelligence\nmachine learning;deep learning"
//
// Resultado esperado:
// ["artificial intelligence", "machine learning", "deep learning"]
const terms = raw
  // Divide el texto usando salto de línea o punto y coma como separadores.
  .split(/\r?\n|;/)

  // Elimina espacios sobrantes en cada término.
  .map(t => t.trim())

  // Elimina elementos vacíos, por ejemplo si hay líneas en blanco
  // o separadores repetidos.
  .filter(Boolean);


// ==========================================
// 3. Generación de un item por término
// ==========================================

// Devuelve un arreglo de objetos con estructura compatible con n8n.
// Cada término se convierte en un item independiente para que el flujo
// lo procese por separado en los siguientes nodos.
return terms.map((term, idx) => ({
  json: {

    // Término original tal como fue escrito por el usuario.
    // Este valor puede usarse directamente en consultas, reportes o trazabilidad.
    termino: term,

    // Versión normalizada del término.
    // Esta transformación ayuda a:
    // - comparar términos sin problemas de mayúsculas/minúsculas
    // - eliminar tildes
    // - quitar caracteres especiales
    // - reducir múltiples espacios a uno solo
    //
    // Ejemplo:
    // "Inteligencia Artificial aplicada!!!"
    // se convierte en:
    // "inteligencia artificial aplicada"
    terminoNormalizado: term
      // Convierte todo a minúsculas
      .toLowerCase()

      // Separa letras base y tildes para poder eliminar los acentos
      .normalize('NFD')

      // Elimina marcas diacríticas, como tildes y otros signos de acentuación
      .replace(/[\u0300-\u036f]/g, '')

      // Reemplaza caracteres especiales por espacios
      // Conserva letras, números y espacios
      .replace(/[^\w\s]/g, ' ')

      // Reduce múltiples espacios consecutivos a un solo espacio
      .replace(/\s+/g, ' ')

      // Elimina espacios al inicio y al final
      .trim(),

    // Año desde el cual se realizará la búsqueda en las APIs o fuentes externas.
    fromYear,

    // Cantidad de resultados solicitados por fuente.
    rows,

    // Número de orden del término dentro de la lista original.
    // Se usa idx + 1 porque los índices del arreglo empiezan en 0,
    // pero para control humano suele ser más claro empezar en 1.
    ordenTermino: idx + 1
  }
}));

const termino = $('Expandir términos').item.json.termino;
const items = Array.isArray($json.message?.items) ? $json.message.items : [];

function clean(text) {
  return String(text || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function norm(text) {
  return clean(text)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

return items.map(item => {
  const titulo = clean(item.title?.[0] || '');
  const resumen = clean(item.abstract || '');
  const doi = clean(item.DOI || '').toLowerCase();
  const enlace = clean(item.URL || '');
  const revista = clean(item['container-title']?.[0] || 'Crossref');
  const autores = (item.author || [])
    .map(a => `${a.given || ''} ${a.family || ''}`.trim())
    .filter(Boolean)
    .join(', ');
  const anio = item.issued?.['date-parts']?.[0]?.[0]
    ? String(item.issued['date-parts'][0][0])
    : '';
  const tituloNormalizado = norm(titulo);
  const resumenNormalizado = norm(resumen);
  const idUnico = doi || `${tituloNormalizado}|${anio}|${norm(revista)}`;

  return {
    json: {
      FuenteAPI: 'Crossref',
      TerminoBusqueda: termino,
      Titulo: titulo,
      TituloNormalizado: tituloNormalizado,
      Resumen: resumen || 'Sin resumen disponible',
      ResumenNormalizado: resumenNormalizado,
      Autor: autores || 'Desconocido',
      Revista: revista,
      FechaPublicacion: anio,
      DOI: doi,
      Enlace: enlace,
      TipoDocumento: clean(item.type || 'journal-article'),
      Citaciones: '',
      OpenAlexID: '',
      SemanticScholarID: '',
      IDUnico: idUnico
    }
  };
}).filter(x => x.json.Titulo);

const termino = $('Expandir términos').item.json.termino;
const items = Array.isArray($json.results) ? $json.results : [];

function clean(text) {
  return String(text || '').replace(/\s+/g, ' ').trim();
}

function norm(text) {
  return clean(text)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function reconstruirAbstract(inverted) {
  if (!inverted || typeof inverted !== 'object') return '';
  const palabras = [];
  for (const [word, positions] of Object.entries(inverted)) {
    for (const pos of positions) {
      palabras[pos] = word;
    }
  }
  return palabras.filter(Boolean).join(' ');
}

return items.map(item => {
  const titulo = clean(item.display_name || item.title || '');
  const resumen = clean(item.abstract || reconstruirAbstract(item.abstract_inverted_index) || '');
  const doi = clean(item.doi || '').replace(/^https?:\/\/doi\.org\//i, '').toLowerCase();
  const enlace = clean(item.primary_location?.landing_page_url || item.primary_location?.pdf_url || item.id || '');
  const revista = clean(item.primary_location?.source?.display_name || 'OpenAlex');
  const autores = (item.authorships || [])
    .map(a => clean(a.author?.display_name || ''))
    .filter(Boolean)
    .join(', ');
  const anio = clean(item.publication_year || '');
  const tituloNormalizado = norm(titulo);
  const resumenNormalizado = norm(resumen);
  const idUnico = doi || `${tituloNormalizado}|${anio}|${norm(revista)}`;

  return {
    json: {
      FuenteAPI: 'OpenAlex',
      TerminoBusqueda: termino,
      Titulo: titulo,
      TituloNormalizado: tituloNormalizado,
      Resumen: resumen || 'Sin resumen disponible',
      ResumenNormalizado: resumenNormalizado,
      Autor: autores || 'Desconocido',
      Revista: revista,
      FechaPublicacion: anio,
      DOI: doi,
      Enlace: enlace,
      TipoDocumento: clean(item.type || 'article'),
      Citaciones: clean(item.cited_by_count || ''),
      OpenAlexID: clean(item.id || ''),
      SemanticScholarID: '',
      IDUnico: idUnico
    }
  };
}).filter(x => x.json.Titulo);

const allItems = $input.all();
function score(item) {
  let s = 0;
  if (item.json.DOI) s += 50;
  if (item.json.Resumen && item.json.Resumen !== 'Sin resumen disponible') s += 20;
  if (item.json.Citaciones !== '' && item.json.Citaciones !== null && item.json.Citaciones !== undefined) s += 10;
  if (item.json.FuenteAPI === 'OpenAlex') s += 5;
  if (item.json.FuenteAPI === 'Crossref') s += 4;
  if (item.json.FuenteAPI === 'Semantic Scholar') s += 3;
  return s;
}
const best = new Map();
for (const item of allItems) {
  const key = item.json.IDUnico || item.json.TituloNormalizado || item.json.Titulo || Math.random().toString(36).slice(2);
  if (!best.has(key) || score(item) > score(best.get(key))) best.set(key, item);
}
return Array.from(best.values());

function limpiar(texto){return String(texto || '').replace(/\s+/g,' ').trim();}
function truncar(texto,max=380){const t=limpiar(texto);return t.length<=max?t:t.slice(0,max-1).trim()+'…';}

function clasificarArea(texto){
  const t = limpiar(texto).toLowerCase();
  const reglas = [
    { area:'Educación', claves:['education','teaching','learning','student','curriculum','pedagog','higher education','university','educacion','docencia','aprendizaje','estudiante','curriculo','pedagog'] },
    { area:'Agricultura', claves:['agriculture','crop','farm','soil','livestock','plant','precision agriculture','agricultura','cultivo','granja','suelo','ganader','planta','riego'] },
    { area:'Salud', claves:['health','clinical','medical','patient','diagnos','hospital','salud','clinic','medic','paciente','diagnost','hospital'] },
    { area:'Negocios', claves:['business','finance','management','market','consumer','negocio','finanza','gestion','mercado','consumidor'] },
    { area:'Ingeniería y tecnología', claves:['computer vision','nlp','deep learning','machine learning','neural network','algorithm','artificial intelligence','vision por computador','aprendizaje profundo','aprendizaje automatico','red neuronal','algoritmo','inteligencia artificial'] }
  ];
  for (const r of reglas){
    if (r.claves.some(c => t.includes(c))) return r.area;
  }
  return 'General';
}

function nivelEvidencia(texto,tipo){
  const t=(texto+' '+tipo).toLowerCase();
  if (/(systematic review|meta-analysis|meta analysis|metaanalysis|revision sistematica|metaanalisis)/.test(t)) return 'Alto';
  if (/(review|survey|scoping review|literature review|revision|estado del arte)/.test(t)) return 'Medio';
  if (/(experiment|case study|empirical|dataset|evaluation|pilot|experimento|estudio de caso|empiric|evaluacion|piloto)/.test(t)) return 'Medio';
  return 'Base';
}

return $input.all().map(item => {
  const j = item.json;
  const baseTexto = `${j.Titulo || ''}. ${j.Resumen || ''}`;
  const area = clasificarArea(baseTexto);
  const evidencia = nivelEvidencia(baseTexto, j.TipoDocumento || '');

  let aplicabilidad = 'Útil para vigilancia científica, revisión de literatura y apoyo en toma de decisiones académicas o de investigación.';
  if (area === 'Educación') aplicabilidad = 'Aplicable a innovación docente, rediseño curricular, integración de IA en la enseñanza y apoyo a procesos de aprendizaje.';
  if (area === 'Agricultura') aplicabilidad = 'Aplicable a agricultura inteligente, monitoreo de cultivos, analítica de datos agropecuarios y apoyo a decisiones productivas.';
  if (area === 'Salud') aplicabilidad = 'Aplicable a apoyo clínico, gestión sanitaria, análisis de datos biomédicos y evaluación de intervenciones.';
  if (area === 'Negocios') aplicabilidad = 'Aplicable a análisis de mercado, optimización operativa, inteligencia competitiva y soporte gerencial.';
  if (area === 'Ingeniería y tecnología') aplicabilidad = 'Aplicable a desarrollo de sistemas inteligentes, automatización, visión por computador y analítica avanzada.';

  const resumenEjecutivo = truncar(j.Resumen && j.Resumen !== 'Sin resumen disponible'
    ? `${j.Titulo}. ${j.Resumen}`
    : `${j.Titulo}. Registro recuperado desde ${j.FuenteAPI || 'fuente externa'} sin resumen disponible.`);

  const recomendacion = evidencia === 'Alto'
    ? 'Priorizar para revisión detallada y posible citación en marcos teóricos o estados del arte.'
    : evidencia === 'Medio'
      ? 'Revisar pertinencia metodológica y usar como referencia complementaria.'
      : 'Validar contenido antes de incorporarlo como referencia principal.';

  return {
    json: {
      ...j,
      ResumenEjecutivo: resumenEjecutivo,
      Aplicabilidad: aplicabilidad,
      RecomendacionUso: recomendacion,
      AreaTematica: area,
      NivelEvidencia: evidencia,
      PalabrasClave: (j.TituloNormalizado || '').split(' ').filter(w => w.length > 3).slice(0, 8).join(', '),
      FechaCaptura: new Date().toISOString()
    }
  };
});

const items = $input.all();

const columnas = [
  'IDUnico',
  'FuenteAPI',
  'TerminoBusqueda',
  'Titulo',
  'TituloNormalizado',
  'Resumen',
  'ResumenNormalizado',
  'ResumenEjecutivo',
  'Aplicabilidad',
  'RecomendacionUso',
  'AreaTematica',
  'NivelEvidencia',
  'Autor',
  'Revista',
  'FechaPublicacion',
  'TipoDocumento',
  'Citaciones',
  'DOI',
  'OpenAlexID',
  'SemanticScholarID',
  'Enlace',
  'PalabrasClave',
  'FechaCaptura'
];

function csvEscape(value) {
  const text = String(value ?? '').replace(/"/g, '""');
  return `"${text}"`;
}

const filas = [
  columnas.join(','),
  ...items.map(({ json }) => columnas.map(col => csvEscape(json[col])).join(','))
];

const csv = '\ufeff' + filas.join('\n');
const fecha = new Date().toISOString().slice(0, 10);
const fileName = `vigilancia_cientifica_${fecha}.csv`;

return [{
  json: {
    fileName,
    totalRegistros: items.length,
    mensaje: 'Archivo CSV generado correctamente'
  },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName
    }
  }
}];
